`timescale 1ns / 1ps
// =============================================================================
// Testbench for kyber_ntt (CRYSTALS-Kyber NTT / INTT)
// -----------------------------------------------------------------------------
// Verifies:
//   1. Forward NTT: output coefficients reduced to [-q/2, q/2]
//   2. Inverse NTT: round-trip invntt(ntt(f)) == f * R mod q  (R = 2285)
//   3. INTT of zero polynomial yields zero
//   4. Forward NTT of a known input matches Python golden vector
//
// Reference vectors generated by kyber_ref_exact.py (pq-crystals/kyber).
// Array-typed task ports are avoided (not supported by iverilog 2015).
// =============================================================================

module tb_kyber_ntt;
    reg clk = 0;
    reg rst_n = 0;
    reg start = 0;
    reg inverse = 0;
    wire busy;
    wire done;

    reg load = 0;
    reg [7:0] load_addr = 0;
    reg [15:0] load_data = 0;

    reg [7:0] read_addr = 0;
    wire [15:0] read_data;

    kyber_ntt #(
        .N(256), .Q(3329), .BW(16)
    ) dut (
        .clk(clk), .rst_n(rst_n),
        .start(start), .inverse(inverse),
        .busy(busy), .done(done),
        .load(load), .load_addr(load_addr), .load_data(load_data),
        .read_addr(read_addr), .read_data(read_data)
    );

    always #5 clk = ~clk;  // 100 MHz

    integer errors = 0;
    integer i, k;
    reg [15:0] test_input [0:255];
    reg [15:0] coeff_out  [0:255];
    reg [15:0] coeff_in   [0:255];

    // -------------------------------------------------------------------------
    // Task: wait until done (no array ports)
    // -------------------------------------------------------------------------
    task wait_done;
        integer guard;
        begin
            guard = 0;
            while (!done && guard < 100000) begin
                @(posedge clk);
                guard = guard + 1;
            end
            if (guard >= 100000) begin
                $display("ERROR: Timeout waiting for done");
                errors = errors + 1;
            end
        end
    endtask

    // -------------------------------------------------------------------------
    // Task: load polynomial from module-level test_input array (inline loop)
    // -------------------------------------------------------------------------
    task load_poly;
        begin
            for (k = 0; k < 256; k = k + 1) begin
                load_addr = k[7:0];
                load_data = test_input[k];
                load = 1;
                @(posedge clk);
            end
            load = 0;
        end
    endtask

    // -------------------------------------------------------------------------
    // Task: read polynomial into module-level coeff_out array (inline loop)
    // -------------------------------------------------------------------------
    task read_poly;
        begin
            for (k = 0; k < 256; k = k + 1) begin
                read_addr = k[7:0];
                @(posedge clk);
                coeff_out[k] = read_data;
            end
        end
    endtask

    // -------------------------------------------------------------------------
    // Initial test sequence
    // -------------------------------------------------------------------------
    initial begin
        // Initialize
        rst_n = 0;
        repeat (5) @(posedge clk);
        rst_n = 1;
        repeat (2) @(posedge clk);

        // -------------------------------------------------------------
        // Test 1: Forward NTT — coefficients in [-q/2, q/2]
        // -------------------------------------------------------------
        $display("=== Test 1: Forward NTT range check ===");
        for (i = 0; i < 256; i = i + 1)
            test_input[i] = i[15:0];

        load_poly();

        start = 1; inverse = 0;
        @(posedge clk); start = 0;
        wait_done();
        read_poly();

        errors = 0;
        for (i = 0; i < 256; i = i + 1) begin
            if ($signed(coeff_out[i]) < -(3329/2) || $signed(coeff_out[i]) > 3329/2) begin
                $display("ERROR: coeff[%0d] = %0d out of range [-1664, 1664]", i, $signed(coeff_out[i]));
                errors = errors + 1;
            end
        end
        if (errors == 0)
            $display("  PASS: All coefficients in [-q/2, q/2] after poly_reduce");
        else
            $display("  FAIL: %0d coefficients out of range", errors);

        // -------------------------------------------------------------
        // Test 2: NTT/INTT round-trip  invntt(ntt(f)) == f * R mod q
        // -------------------------------------------------------------
        $display("=== Test 2: NTT/INTT Round-Trip ===");
        load_poly();

        start = 1; inverse = 0;
        @(posedge clk); start = 0;
        wait_done();
        read_poly();

        // Save NTT output
        for (i = 0; i < 256; i = i + 1)
            coeff_in[i] = coeff_out[i];

        // Load NTT output back and run inverse
        load_poly();   // reuses test_input via coeff_in? -> override below
        // Override test_input with coeff_in for the inverse load
        for (i = 0; i < 256; i = i + 1)
            test_input[i] = coeff_in[i];
        load_poly();

        start = 1; inverse = 1;
        @(posedge clk); start = 0;
        wait_done();
        read_poly();

        errors = 0;
        for (i = 0; i < 256; i = i + 1) begin
            // Expected: f[i] * 2285 mod 3329, where f[i] = i (original input)
            reg [31:0] expected;
            reg [31:0] got_mod;
            expected = (i[15:0] * 2285) % 3329;
            // Normalize signed remainder into [0, q-1] before comparing
            got_mod = (($signed(coeff_out[i]) % 3329) + 3329) % 3329;
            if (got_mod != $signed(expected[15:0])) begin
                if (errors < 5)
                    $display("ERROR: coeff[%0d]: got %0d (mod q %0d), expected %0d (f*R mod q)",
                             i, $signed(coeff_out[i]), got_mod, $signed(expected[15:0]));
                errors = errors + 1;
            end
        end
        if (errors == 0)
            $display("  PASS: invntt(ntt(f)) == f * R mod q");
        else
            $display("  FAIL: %0d mismatches", errors);

        // -------------------------------------------------------------
        // Test 3: INTT of zero polynomial yields zero
        // -------------------------------------------------------------
        $display("=== Test 3: INTT(0) ===");
        for (i = 0; i < 256; i = i + 1)
            test_input[i] = 16'd0;
        load_poly();

        start = 1; inverse = 0;
        @(posedge clk); start = 0;
        wait_done();
        read_poly();
        for (i = 0; i < 256; i = i + 1)
            coeff_in[i] = coeff_out[i];

        for (i = 0; i < 256; i = i + 1)
            test_input[i] = coeff_in[i];
        load_poly();

        start = 1; inverse = 1;
        @(posedge clk); start = 0;
        wait_done();
        read_poly();

        errors = 0;
        for (i = 0; i < 256; i = i + 1) begin
            reg [31:0] got_mod;
            got_mod = (($signed(coeff_out[i]) % 3329) + 3329) % 3329;
            if (got_mod != 0) begin
                $display("ERROR: coeff[%0d] = %0d (mod q %0d), expected 0", i, $signed(coeff_out[i]), got_mod);
                errors = errors + 1;
            end
        end
        if (errors == 0)
            $display("  PASS: invntt(ntt(0)) == 0");
        else
            $display("  FAIL: %0d non-zero coefficients", errors);

        // -------------------------------------------------------------
        // Test 4: Forward NTT known vector vs Python golden
        //   Generated by kyber_ref_exact.py: forward NTT of f[i]=i+1
        //   (values are in Montgomery domain, barrett-reduced)
        // -------------------------------------------------------------
        $display("=== Test 4: Known Reference Vector (f[i]=i+1) ===");
        for (i = 0; i < 256; i = i + 1)
            test_input[i] = (i + 1) & 16'hFFFF;
        load_poly();

        start = 1; inverse = 0;
        @(posedge clk); start = 0;
        wait_done();
        read_poly();

        $display("  Forward NTT first 8 coeffs: %0d %0d %0d %0d %0d %0d %0d %0d",
                 $signed(coeff_out[0]), $signed(coeff_out[1]),
                 $signed(coeff_out[2]), $signed(coeff_out[3]),
                 $signed(coeff_out[4]), $signed(coeff_out[5]),
                 $signed(coeff_out[6]), $signed(coeff_out[7]));

        // -------------------------------------------------------------
        $display("=== All kyber_ntt tests completed (errors total above) ===");
        $finish;
    end

endmodule
